const assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm'),path=require('node:path'),root=path.resolve(__dirname,'..'),app=fs.readFileSync(path.join(root,'app.js'),'utf8');
const start=app.indexOf("(function(g){\n const M=g.MSOS4,U=M.util,S=M.session;\n const P=M.parser={};");assert.ok(start>=0,'base parser section not found');const end=app.indexOf("\n\n(function(g){\n const M=g.MSOS4,U=M.util,S=M.session;\n const C=M.changes={};",start);assert.ok(end>start,'base parser section end not found');
const U={text:v=>String(v??'').replace(/\s+/g,' ').trim(),lines:v=>String(v??'').replace(/\r/g,'').split('\n'),hash:s=>{let h=2166136261;for(const ch of String(s??'')){h^=ch.charCodeAt(0);h=Math.imul(h,16777619)}return(h>>>0).toString(36)},stableId:(prefix,...parts)=>`${prefix}-${parts.map(x=>String(x??'').trim().toLowerCase()).join('|')}`,now:()=> '2026-08-25T02:50:00.000Z',deepFreeze:o=>o,blockType:v=>{const s=String(v??'').trim().toLowerCase();if(/warm.?up/.test(s))return'warm_up';if(/pre.?set/.test(s))return'pre_set';if(/main/.test(s))return'main_set';if(/post.?set|reinforcement/.test(s))return'post_set';if(/warm.?down|cool.?down/.test(s))return'warm_down';if(/test/.test(s))return'test';return'other'},blockTitle:t=>({warm_up:'Warm-up',pre_set:'Pre-set',main_set:'Main set',post_set:'Post-set',warm_down:'Warm-down',test:'Test',other:'Other'})[t]||'Block'};
const S={};S.empty=(identity={},source='')=>({schema:4,id:identity.id||'s',identity:{...identity},originalPlan:{text:String(source).trim()},currentSource:{text:String(source).trim()},blocks:[],changes:[],finish:null,metadata:{},updatedAt:U.now()});S.itemDistance=item=>!item?0:item.kind==='set'?Math.max(0,Number(item.reps)||1)*Math.max(0,Number(item.distance)||0):item.kind==='group'?Math.max(1,Number(item.rounds)||1)*(item.items||[]).reduce((n,x)=>n+S.itemDistance(x),0):0;S.blockDistance=b=>(b?.items||[]).reduce((n,x)=>n+S.itemDistance(x),0);S.total=s=>(s?.blocks||[]).reduce((n,b)=>n+S.blockDistance(b),0);global.MSOS4={util:U,session:S};vm.runInThisContext(app.slice(start,end),{filename:'app-parser-section.js'});require('../engines/parser-semantics.js');
function verify(source,label){const s=global.MSOS4.parser.parse(source,{id:label,course:'SCM',squads:['National']});assert.equal(S.total(s),2100,`${label}: total`);assert.equal(s.blocks.length,1,`${label}: block count`);const block=s.blocks[0];assert.equal(S.blockDistance(block),2100,`${label}: block total`);assert.equal(block.items.length,1,`${label}: top-level item count`);const group=block.items[0];assert.equal(group.kind,'group',`${label}: parent kind`);assert.equal(Number(group.rounds),3,`${label}: rounds`);assert.equal(group.items.length,2,`${label}: group children`);const [thr,easy]=group.items;assert.equal(thr.kind,'set');assert.equal(Number(thr.reps),5);assert.equal(Number(thr.distance),100);assert.match(String(thr.raw||thr.text||''),/Threshold/i);assert.equal(easy.kind,'set');assert.equal(Number(easy.reps),1);assert.equal(Number(easy.distance),200);assert.match(String(easy.raw||easy.text||''),/Easy/i);assert.equal(S.itemDistance(group),2100,`${label}: group total`);assert.equal(s.originalPlan.text,source,`${label}: original plan preserved`);assert.equal(s.currentSource.text,source,`${label}: current source preserved`);return s;}
verify(`MAIN SET\n3 x (5 x 100 Threshold + 200 Easy)`,'literal-plus-sign');
verify(`MAIN SET\n3 x (5 x 100 Threshold, 200 Easy)`,'single-line');
verify(`MAIN SET\n3 x (\n5 x 100 Threshold\n200 Easy\n)`,'multi-line');
